import paramiko
from scp import SCPClient


class FileCopier(object):
    def __init__(self, host, user, password, port=22):
        self.host = host
        self.port = port
        self.user = user
        self.password = password

    def put(self, local_path, remote_path):
        self._put_or_get('put', local_path, remote_path)

    def get(self, remote_path, local_path):
        self._put_or_get('get', local_path, remote_path)

    def _put_or_get(self, put_or_get, local_path, remote_path):
        with paramiko.SSHClient() as ssh:
            ssh.load_system_host_keys()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(self.host, self.port, self.user, self.password)
            with SCPClient(ssh.get_transport()) as scp:
                if put_or_get == 'put':
                    scp.put(files=local_path, remote_path=remote_path, recursive=True)
                elif put_or_get == 'get':
                    scp.get(remote_path=remote_path, local_path=local_path, recursive=True)
